import re
import logging
from taf.ul.sc.perf.tc import tc
from taf.ul.coop import coop  # type: ignore
from taf.ul.teb import teb  # type: ignore
from taf.ul.sc.perf.util.logger import log_debug_function_info, log_function_status_to_console
from taf.ul.sc.perf.messenger import get_receivers_for_recovery

# try:
from urllib.parse import urlencode
# except ImportError:
#     from urllib import urlencode


class CoopInterface(object):

    @log_function_status_to_console(msg="Add results to COOP", log_hierarchy=2, ignore_exception=True)
    @log_debug_function_info()
    def add_results_to_coop(self):
        coop_url = tc.run_params['environment']['coop_url']
        proxy = tc.run_params['environment']['lab_proxy']

        business_line = tc.run_params['add_results_to_coop']['business_line']
        product = tc.run_params['add_results_to_coop']['product']
        test_hierarchy = tc.run_params['add_results_to_coop']['test_hierarchy']

        if product.upper() == 'RTG':
            build_id = tc.stats['DB']['string properties']['ue build']
            branch = self.get_rtg_release_version_based_on_build(build=build_id)
            build_type = 'ue build'
        else:
            build_id = tc.bts_build
            branch = tc.bts_release
            build_type = 'bts build'

        provider_email = get_receivers_for_recovery()
        test_case_name = tc.test_case_name

        block_url = type(self)._get_url_to_all_test_cases_in_block(build_id, business_line, product, test_hierarchy)
        url = type(self)._get_url_to_all_test_case_executions(build_id, business_line, product, test_hierarchy,
                                                              test_case_name)
        start = tc.stats['DB']['integer properties']['start test timestamp']
        end = tc.stats['DB']['integer properties']['stop test timestamp']

        statuses_count = self._get_all_test_cases_statuses_counts(build_type=build_type,
                                                                  build=build_id,
                                                                  test_hierarchy=test_hierarchy,
                                                                  test_case_name=test_case_name)
        result = 'PASS' if statuses_count['failcount'] == 0 else 'FAIL'

        report_coop_params = {
            'business_line': business_line,
            'product': product,
            'test_hierarchy': test_hierarchy,
            'build_id': build_id,
            'branch': branch,
            'block_url': block_url,
            'name': test_case_name,
            'result': result,
            'url': url,
            'start': start,
            'end': end,
            'provider_email': ";".join(provider_email),
            'passcount': statuses_count["passcount"],
            'failcount': statuses_count["failcount"]
        }

        logging.debug("Reported params: {}".format(report_coop_params))

        cp = coop(base_coop_url=coop_url,
                  proxies={'http': proxy, 'https': proxy})

        cp.report_single_test_case(**report_coop_params)

    @staticmethod
    def get_rtg_release_version_based_on_build(build):
        # RTG_RL14.0_BLD-03
        sw_release = None
        regex = re.compile(r'^RTG_(?P<RELEASE>.*?)_')
        match = regex.search(build)
        if match:
            sw_release = match.group('RELEASE')

        return sw_release

    @staticmethod
    def _get_url_to_all_test_cases_in_block(build, bl, product, test_hierarchy):
        url_params = {
            'string:coop business line': bl,
            'string:coop product': product,
            'string:coop test hierarchy': test_hierarchy
        }

        if product.upper() == 'RTG':
            url_params['string:ue build'] = build
        else:
            url_params['string:bts build'] = build

        url_encoded = urlencode(url_params, doseq=True)
        base_url = CoopInterface._get_base_results_url()

        result_url = "{}&{}".format(base_url, url_encoded)

        return result_url

    @staticmethod
    def _get_url_to_all_test_case_executions(build, bl, product, test_hierarchy, tc_name):

        url_params = {
            'string:test case name': tc_name
        }

        url_encoded = urlencode(url_params)
        block_url = CoopInterface._get_url_to_all_test_cases_in_block(build, bl, product, test_hierarchy)

        result_url = "{}&{}".format(block_url, url_encoded)

        return result_url

    @staticmethod
    def _get_base_results_url():

        teb_url = tc.run_params['environment']['teb_url']
        url_params = {
            'valid run': 1,
            'table': 'normal',
            'output': 'normal',
            'devices': 2,
            'column_sets': [256]
        }
        url_encoded = urlencode(url_params, doseq=True)

        base_search_url = "{}{}{}".format(teb_url,
                                          '/search_results?',
                                          url_encoded)

        return base_search_url

    @staticmethod
    def _get_all_test_cases_statuses_counts(build_type, build, test_hierarchy, test_case_name):
        url = tc.run_params['environment']['teb_url']
        url_params = {
            'valid run': '1',
            'private': '0',
            'column_sets': '256',
            'table': 'normal',
            'output': 'normal',
            'string:{}'.format(build_type): build,
            'string:coop test hierarchy': test_hierarchy,
            'string:test case name': test_case_name
        }
        response = teb.get_query_result(url, url_params)
        return teb.get_all_test_cases_statuses_count(response)
